async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then(r => r.json()),
      fetch('/api/notifications').then(r => r.json()),
      fetch('/api/settings').then(r => r.json())
    ]);

    return { analytics, notifications, settings };
  } catch {
    // Return mock data for build time
    return {
      analytics: { visitors: 1250, pageViews: 5420, bounceRate: 42.5 },
      notifications: [
        { id: 1, message: 'Welcome to your dashboard!', read: false },
        { id: 2, message: 'System update scheduled for tonight.', read: true }
      ],
      settings: { theme: 'light', notifications: true, language: 'en' }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div style={{ padding: '20px', maxWidth: '1200px', margin: '0 auto' }}>
      <h2>Dashboard</h2>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '20px' }}>
        {/* Analytics Section */}
        <section style={{ border: '1px solid #e5e7eb', borderRadius: '8px', padding: '20px' }}>
          <h3>Analytics</h3>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
            <div>
              <strong>Visitors:</strong> {analytics.visitors}
            </div>
            <div>
              <strong>Page Views:</strong> {analytics.pageViews}
            </div>
            <div>
              <strong>Bounce Rate:</strong> {analytics.bounceRate}%
            </div>
          </div>
        </section>

        {/* Notifications Section */}
        <section style={{ border: '1px solid #e5e7eb', borderRadius: '8px', padding: '20px' }}>
          <h3>Notifications</h3>
          <div style={{ maxHeight: '200px', overflow: 'auto' }}>
            {notifications.map(notification => (
              <div key={notification.id} style={{ 
                padding: '10px', 
                marginBottom: '5px', 
                backgroundColor: notification.read ? '#f3f4f6' : '#eff6ff',
                borderRadius: '4px'
              }}>
                {notification.message}
              </div>
            ))}
          </div>
        </section>

        {/* Settings Section */}
        <section style={{ border: '1px solid #e5e7eb', borderRadius: '8px', padding: '20px' }}>
          <h3>Settings</h3>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
            <div>
              <strong>Theme:</strong> {settings.theme}
            </div>
            <div>
              <strong>Notifications:</strong> {settings.notifications ? 'Enabled' : 'Disabled'}
            </div>
            <div>
              <strong>Language:</strong> {settings.language}
            </div>
          </div>
        </section>
      </div>
    </div>
  );
}

